class ExamTracker {
  private final int[] times = new int[100_001];
  private final long[] prefix = new long[100_002];
  private int size;

  public ExamTracker() {}

  public void record(int time, int score) {
    times[size] = time;
    prefix[size + 1] = prefix[size] + score;
    size++;
  }

  private int lowerBound(int x) {
    int lo = 0, hi = size;
    while (lo < hi) {
      int mid = (lo + hi) >>> 1;
      if (times[mid] < x) lo = mid + 1;
      else hi = mid;
    }
    return lo;
  }

  public long totalScore(int startTime, int endTime) {
    return prefix[lowerBound(endTime + 1)] - prefix[lowerBound(startTime)];
  }
}
